import json
import os
import pandas as pd
import numpy as np

DATA_FILE = "/home/chs/Work/tga_plot/tests/inputs/blank_rows_on_top.xlsx"

# Read the sheet without assuming the header is at the top; row 8 contains column names.
raw = pd.read_excel(DATA_FILE, sheet_name="Sheet1", header=None, engine="openpyxl")

header_row = 7  # Excel row 8 (zero-based index 7)
headers = raw.iloc[header_row].astype(str).str.strip()
data = raw.iloc[header_row + 1:].copy()
data.columns = headers

# Columns C, D and E correspond to Temperature, Weight(%) and D.W(%/C).
x = pd.to_numeric(data.iloc[:, 2], errors="coerce")
y1 = pd.to_numeric(data.iloc[:, 3], errors="coerce")
y2 = pd.to_numeric(data.iloc[:, 4], errors="coerce")

valid = x.notna() & (y1.notna() | y2.notna())
x, y1, y2 = x[valid], y1[valid], y2[valid]

option = {
    "animation": False,
    "title": {
        "text": "TGA",
        "left": "center",
        "textStyle": {"fontFamily": "Noto Sans CJK KR"}
    },
    "tooltip": {
        "trigger": "axis",
        "axisPointer": {"type": "cross"}
    },
    "legend": {
        "data": ["Weight(%)", "D.W(%/C)"],
        "top": 32,
